"""Reproducible A-share opportunity research over the bundled Vibe factor zoo.

This is a native research adapter, not an order engine. Method selection uses
only training/validation dates; the final chronological holdout is evaluation.
"""
from __future__ import annotations

import importlib
import math
import re
from typing import Any

import numpy as np
import pandas as pd
from scipy import stats
from sklearn.ensemble import RandomForestRegressor
from sklearn.linear_model import Ridge

from src.factors.registry import get_default_registry
from src.quantlib.multipletesting import benjamini_hochberg


def _number(value: Any) -> float | None:
    return float(value) if value is not None and np.isfinite(value) else None


def _zscore(values: pd.DataFrame) -> pd.DataFrame:
    std = values.std(axis=1).where(lambda x: x > 1e-12)
    return values.sub(values.mean(axis=1), axis=0).div(std, axis=0)


def _ic(values: pd.DataFrame, target: pd.DataFrame) -> pd.Series:
    valid = values.notna() & target.notna()
    left = values.where(valid).rank(axis=1)
    right = target.where(valid).rank(axis=1)
    return left.corrwith(right, axis=1).where(valid.sum(axis=1) >= 5)


def _metrics(values: pd.DataFrame, target: pd.DataFrame, calibrated: bool = True) -> dict:
    valid = values.notna() & target.notna()
    errors = (values - target).where(valid).to_numpy(dtype=float)
    ics = _ic(values, target).dropna()
    return {
        "rank_ic": _number(ics.mean()), "ic_dates": len(ics),
        "mae": _number(np.nanmean(np.abs(errors))) if calibrated and valid.any().any() else None,
        "rmse": _number(np.sqrt(np.nanmean(errors ** 2))) if calibrated and valid.any().any() else None,
        "coverage": float(valid.sum().sum() / max(1, target.notna().sum().sum())),
        "observations": int(valid.sum().sum()),
    }


def _zoo_engine():
    return importlib.import_module("src.skills.multi-factor.zoo_signal_engine").ZooSignalEngine


def _factor_name(source: str, meta: dict, factor_id: str) -> str:
    match = re.search(r"中文名称:\s*([^\r\n]+)", source)
    return match.group(1).strip() if match else meta.get("nickname") or factor_id


def _factor_failure(exc: Exception) -> str:
    message = str(exc).lower()
    for fragment, reason in (
        ("historical_prefix_changed", "historical_prefix_changed"),
        (">95% nan", "insufficient_finite_factor_values"),
        ("+/- inf", "non_finite_factor_values"),
        ("output shape", "factor_output_shape_mismatch"),
        ("panel missing", "undeclared_input_unavailable"),
        ("import failed", "native_factor_import_failed"),
    ):
        if fragment in message:
            return reason
    return "native_factor_computation_failed:" + type(exc).__name__


def _tree_contributions(model, values: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """Exact tree-path decomposition; increments sum to prediction - root mean."""
    out = np.zeros_like(values, dtype=float)
    baseline = np.zeros(len(values), dtype=float)
    for estimator in model.estimators_:
        tree = estimator.tree_
        baseline += float(tree.value[0, 0, 0]) / len(model.estimators_)
        for row, sample in enumerate(values):
            node = 0
            while tree.children_left[node] != tree.children_right[node]:
                feature = tree.feature[node]
                child = tree.children_left[node] if np.float32(sample[feature]) <= tree.threshold[node] else tree.children_right[node]
                out[row, feature] += (tree.value[child, 0, 0] - tree.value[node, 0, 0]) / len(model.estimators_)
                node = child
    return out, baseline


def compute_opportunities(
