        spaced = ics.iloc[::horizon]
        if len(spaced) >= 12 and spaced.std() > 1e-12:
            p_value = stats.ttest_1samp(spaced.to_numpy(), 0.0).pvalue
            if np.isfinite(p_value):
                p_ids.append(factor_id)
                p_values.append(float(p_value))
    bh = benjamini_hochberg(p_values, fdr=.05) if p_values else None
    if bh is not None:
        for idx, factor_id in enumerate(p_ids):
            by_id[factor_id].update(training_p_value=p_values[idx], bh_adjusted_p=float(bh.adjusted_p_values[idx]), bh_rejected=bool(bh.rejected[idx]))
    if scheme_id == "low_volatility":
        preferred = {"qlib158_std20": -1.0, "qlib158_std60": -1.0, "academic_illiq": -1.0}
        selected = [factor_id for factor_id in preferred if factor_id in train_scores]
        directions = {factor_id: preferred[factor_id] for factor_id in selected}
    else:
        # Train-only direction learning and redundancy pruning. The feature cap
        # bounds model complexity, not the number of native factors audited.
        selected, directions = [], {}
        for factor_id in sorted(train_scores, key=lambda x: (-abs(train_scores[x]), x)):
            z = standardized[factor_id].loc[train_dates].to_numpy().ravel()
            redundant = False
            for existing in selected:
                other = standardized[existing].loc[train_dates].to_numpy().ravel()
                mask = np.isfinite(z) & np.isfinite(other)
                if mask.sum() >= 100 and abs(np.corrcoef(z[mask], other[mask])[0, 1]) >= .90:
                    by_id[factor_id]["selection_reason"] = "training_redundant_with:" + existing
                    redundant = True
                    break
            if not redundant:
                selected.append(factor_id)
                directions[factor_id] = 1.0 if train_scores[factor_id] >= 0 else -1.0
            if len(selected) == 16:
                break
    if not selected:
        raise ValueError("No native factors have sufficient causal training coverage")
    for item in audit:
        if item["factor_id"] in selected:
            item.update(selected=True, selection_reason="fixed_low_volatility_semantics" if scheme_id == "low_volatility" else "training_ic_and_redundancy_filter", direction=directions[item["factor_id"]])
        elif item["status"] == "computed" and "selection_reason" not in item:
            item["selection_reason"] = "not_in_scheme" if scheme_id == "low_volatility" else "training_feature_budget"
    if progress is not None:
        progress({"stage": "models", "selected_factors": len(selected)})
    shape = close.shape
    features = np.stack([standardized[x].to_numpy(dtype=float) for x in selected], axis=-1)
    flat_features = features.reshape(-1, len(selected))
    # Row-wise z-scores carry no future dates; missing values remain missing for
    # native composites. ML uses a train-fitted median, disclosed per result.
    train_values = features[train_rows].reshape(-1, len(selected))
    medians = np.nanmedian(train_values, axis=0)
    medians = np.where(np.isfinite(medians), medians, 0.0)
    imputed = np.where(np.isfinite(flat_features), flat_features, medians)
    training_target = target.iloc[train_rows].to_numpy().ravel()
    training_valid = np.isfinite(training_target) & (np.isfinite(train_values).mean(axis=1) >= .75)
    if training_valid.sum() < 200:
        raise ValueError("Not enough observed training examples for model comparison")
    observed_coverage = np.isfinite(features).mean(axis=2)

    class _CachedRegistry:
        def compute(self, factor_id, input_panel):
            return raw[factor_id].reindex_like(input_panel["close"])

    engine_cls = _zoo_engine()
    predictions, models, model_weights, calibrations = {}, {}, {}, {}
    model_records = []
    for model_id in ("equal_weight", "ic_weight"):
        weights = [directions[x] * (abs(train_scores[x]) if model_id == "ic_weight" else 1.0) for x in selected]
        composite = engine_cls.from_zoo(selected, weights=weights, registry=_CachedRegistry()).compute_signal(panel)
        norm = max(sum(abs(x) for x in weights), 1e-12)
        model_weights[model_id] = np.asarray(weights) / norm
        if scheme_id == "low_volatility":
            slope, intercept = 1.0, 0.0
        else:
            score = composite.iloc[train_rows].to_numpy().ravel()
            mask = training_valid & np.isfinite(score)
            if mask.sum() < 200 or np.nanstd(score[mask]) < 1e-12:
                model_records.append({"id": model_id, "status": "not_run", "reason": "insufficient_complete_composite_training_rows"})
                continue
            calibration = Ridge(alpha=1.0).fit(score[mask].reshape(-1, 1), training_target[mask])
            slope, intercept = float(calibration.coef_[0]), float(calibration.intercept_)
        calibrations[model_id] = (slope, intercept)
        predictions[model_id] = composite * slope + intercept
    if scheme_id == "multifactor":
        models = {
            "ridge": Ridge(alpha=10.0),
            "random_forest": RandomForestRegressor(n_estimators=64, max_depth=4, min_samples_leaf=32, max_features=.75, n_jobs=1, random_state=42),
        }
        for model_id, model in models.items():
            model.fit(np.where(np.isfinite(train_values), train_values, medians)[training_valid], training_target[training_valid])
            values = model.predict(imputed).reshape(shape)
            predictions[model_id] = pd.DataFrame(values, index=close.index, columns=close.columns).where((observed_coverage >= .75) & close.notna())
    common_validation = target.loc[validation_dates].notna()
    for values in predictions.values():
        common_validation &= values.loc[validation_dates].notna()
    for model_id, values in predictions.items():
        validation = _metrics(values.loc[validation_dates].where(common_validation), target.loc[validation_dates], calibrated=scheme_id != "low_volatility")
        parameters = (
            {"factor_weights": dict(zip(selected, model_weights[model_id].tolist())), "training_calibration_slope": calibrations[model_id][0], "training_calibration_intercept": calibrations[model_id][1]}
            if model_id in calibrations else models[model_id].get_params()
        )
        model_records.append({"id": model_id, "status": "evaluated", "validation": validation, "parameters": parameters})
    if scheme_id == "low_volatility":
        model_records.extend({"id": model_id, "status": "not_run", "reason": "fixed_low_volatility_semantics_not_return_prediction"} for model_id in ("ridge", "random_forest"))
    usable = [x for x in model_records if x["status"] == "evaluated" and x["validation"]["rank_ic"] is not None and x["validation"]["coverage"] >= .5]
    if not usable:
        raise ValueError("No model has sufficient out-of-sample validation coverage")
    selected_model = "equal_weight" if scheme_id == "low_volatility" else max(usable, key=lambda x: (x["validation"]["rank_ic"], -x["validation"]["mae"]))["id"]
    if selected_model not in predictions:
        raise ValueError("Fixed low-volatility method lacks sufficient coverage")
    prediction = predictions[selected_model].where(close.notna())
    holdout = _metrics(prediction.loc[test_dates], target.loc[test_dates], calibrated=scheme_id != "low_volatility")
    latest = prediction.iloc[-1].dropna().sort_values(ascending=False, kind="stable")
    current_features = imputed.reshape(*shape, len(selected))[-1]
    if selected_model in calibrations:
        slope, intercept = calibrations[selected_model]
        contributions = features[-1] * model_weights[selected_model] * slope
        baselines = np.full(len(close.columns), intercept)
    elif selected_model == "ridge":
        model = models[selected_model]
        contributions = current_features * model.coef_
        baselines = np.full(len(close.columns), float(model.intercept_))
    else:
        contributions, baselines = _tree_contributions(models[selected_model], current_features)
    candidates = []
    returns = close.pct_change(fill_method=None)
    volatility = returns.tail(20).std() * math.sqrt(252)
    for rank, (symbol, score) in enumerate(latest.items(), 1):
        column = close.columns.get_loc(symbol)
        parts = [{
            "factor_id": factor_id, "name": by_id[factor_id].get("name", factor_id),
            "value": _number(raw[factor_id].iloc[-1, column]),
            "standardized_value": _number(features[-1, column, idx]),
            "contribution": _number(contributions[column, idx]),
            "imputed": not bool(np.isfinite(features[-1, column, idx])),
        } for idx, factor_id in enumerate(selected)]
        parts.sort(key=lambda x: abs(x["contribution"] or 0), reverse=True)
        positive = [x for x in parts if (x["contribution"] or 0) > 0][:3]
        negative = [x for x in parts if (x["contribution"] or 0) < 0][:2]
        series = close[symbol].dropna()
        drawdown = float((series.tail(20) / series.tail(20).cummax() - 1).min()) if len(series) else None
        risks = []
        if np.isfinite(volatility[symbol]):
            risks.append(f"近20日年化波动率 {volatility[symbol]:.1%}，仅描述历史波动")
        if drawdown is not None:
            risks.append(f"近20日区间内最大回撤 {drawdown:.1%}")
        if observed_coverage[-1, column] < 1:
            risks.append(f"本次入模因子实际覆盖 {observed_coverage[-1, column]:.0%}；模型缺项使用训练段中位数")
        if holdout["rank_ic"] is not None and holdout["rank_ic"] <= 0:
            risks.append("本次方法独立测试期排序相关性未呈正向，结果仅供继续研究")
        candidates.append({
            "symbol": str(symbol), "rank": rank, "score": float(score),
            "last_price": _number(close.iloc[-1, column]),
            "change_pct": _number(returns.iloc[-1, column] * 100),
            "as_of": close.index[-1].isoformat(),
            "support": [f"{x['name']}：对本次研究分数贡献 {x['contribution']:+.5f}" for x in positive],
            "counter_evidence": [f"{x['name']}：对本次研究分数贡献 {x['contribution']:+.5f}" for x in negative],
            "contributions": parts, "score_baseline": float(baselines[column]),
            "model_scores": {model_id: _number(values.iloc[-1, column]) for model_id, values in predictions.items()},
            "contribution_method": "tree_path_decomposition" if selected_model == "random_forest" else "linear_additive",
            "risks": risks, "volatility_20d_annualized": _number(volatility[symbol]),
            "max_drawdown_20d": drawdown,
        })
    def _range(dates):
        return {"start": dates[0].isoformat(), "end": dates[-1].isoformat(), "dates": len(dates)}
    validations = [
        {"id": "causality", "label": "因果前缀核对", "status": "completed", "summary": "每项成功因子在两个历史前缀逐值核对；失败项不入模"},
        {"id": "purged_holdout", "label": "独立时间检验", "status": "completed", "summary": "同日股票同组；边界隔离预测周期；验证期择模，测试期只评价", "metrics": holdout},
        {"id": "factor_bh", "label": "因子多重检验", "status": "completed_with_limitations" if bh is not None else "not_run", "summary": f"训练期{len(p_ids)}项可检验因子，BH 5%探索性拒绝{bh.n_rejected if bh is not None else 0}项；不是方法通过认证。IC按预测周期抽样，时序依赖及因子相关性仍影响统计解释"},
        {"id": "cost_backtest", "label": "费用与交易约束回测", "status": "not_run", "summary": "当前排序与收益标签未扣费用，不等于可交易费后收益"},
        {"id": "random_control", "label": "随机策略对照", "status": "not_run", "summary": "未运行同池随机持仓回测对照"},
        {"id": "pbo", "label": "过拟合概率检验", "status": "not_run", "summary": "未形成完整策略试验收益矩阵，未运行CSCV/PBO"},
        {"id": "forward_monitor", "label": "前向跟踪", "status": "not_run", "summary": "本次新产物尚无生成后的真实前向记录"},
    ]
    return {
        "version": 2, "as_of": close.index[-1].isoformat(), "scheme_id": scheme_id,
        "horizon": horizon, "candidates": candidates,
        "factor_audit": {
            "total": len(factor_ids), "computed": len(raw), "selected": len(selected),
            "failed": sum(x["status"] == "failed" for x in audit),
            "excluded": sum(x["status"] == "excluded" for x in audit), "entries": audit,
            "source": "Vibe Registry.compute / bundled full factor zoo",
        },
        "method": {
            "selected_model": selected_model, "models": model_records,
            "selection_rule": "fixed low-volatility native combination" if scheme_id == "low_volatility" else "maximum validation-period daily cross-sectional rank IC; MAE tie-break",
            "score_kind": "native_low_volatility_liquidity_composite" if scheme_id == "low_volatility" else "estimated_horizon_return_relative_to_research_pool",
            "score_warning": "研究分数不是上涨概率、目标价或交易指令",
            "split": {"training": _range(train_dates), "validation": _range(validation_dates), "test": _range(test_dates), "purge_trading_days": horizon, "grouping": "all symbols on the same date stay in the same split"},
            "training_only_factor_selection": True, "independent_test": holdout,
            "validation_comparison": "same observed date-symbol cells across all evaluated models",
            "selected_factors": selected, "directions": directions,
            "source": "Vibe ZooSignalEngine + sklearn Ridge/RandomForest; native research integration",
            "imputation": "ML only: training-segment feature median; minimum observed selected-feature coverage 75%",
        },
        "validations": validations,
        "universe": {"symbols": len(close.columns), "ranked": len(candidates), "not_ranked": [str(x) for x in close.columns if x not in latest.index]},
        "limitations": [
            "仅研究当前明确列出的股票池；当前成分回溯存在幸存者偏差，不代表历史完整市场。",
            "价格复权及数据来源由加载产物记录；前缀一致性不能证明行情历史具备完整PIT语义。",
            "未提供经时点验证的财报/估值/行业数据时，对应因子逐项排除，未填造财务数据。",
            "模型选择未使用独立测试期；本次统计不构成未来有效或盈利证明。",
            "树路径贡献是模型分解，不是因果效应；因子名及原生近似说明保留在审计记录。",
        ],
        "_holdout_signals": prediction.loc[test_dates].copy(),
    }

