"""Thin product projection of the bundled native research teams and artifacts."""
from __future__ import annotations

import csv
import hashlib
import json
import logging
import math
import os
import re
import shutil
import uuid
from datetime import date
from pathlib import Path
from typing import Any

from fastapi import Depends, FastAPI, HTTPException, Query

from src.api.security import require_auth
from src.config.paths import get_runs_dir, get_runtime_root, get_swarm_runs_dir
from src.swarm.models import SwarmTask
from src.swarm.serialization import serialize_task
from src.tools.redaction import redact_payload, redact_tool_result

logger = logging.getLogger(__name__)
NATIVE_TEAM_NAMES = (
    "quant_strategy_desk", "factor_research_committee", "ml_quant_lab",
    "fundamental_research_team", "sector_rotation_team", "event_driven_task_force",
    "equity_research_team", "investment_committee",
)
_ID = re.compile(r"^[A-Za-z0-9_-]{1,128}$")
_SYMBOL = re.compile(r"^\d{6}\.(?:SH|SZ|BJ)$")
_STRATEGY = re.compile(r"^(?:alpha_zoo|sdm):[A-Za-z0-9_.-]{1,128}$")
_MAX_JSON = 16 * 1024 * 1024


def _json_file(path: Path, root: Path, maximum: int = _MAX_JSON) -> Any:
    from src.api.mona_reads import _safe_private_regular_file

    safe = _safe_private_regular_file(path, root)
    if safe is None or safe.stat().st_size > maximum:
        raise ValueError("artifact is unavailable or exceeds the read limit")
    return json.loads(safe.read_text(encoding="utf-8"))


def _run(swarm_id: str):
    from src.swarm.store import SwarmStore

    if not isinstance(swarm_id, str) or not _ID.fullmatch(swarm_id):
        raise HTTPException(status_code=404, detail="Native research not found")
    root = get_swarm_runs_dir()
    path = root / swarm_id
    try:
        from src.api.mona_reads import _safe_private_directory

        if _safe_private_directory(path, get_runtime_root().resolve()) is None:
            raise ValueError("research outside private state")
        _json_file(path / "run.json", get_runtime_root().resolve())
        store = SwarmStore(base_dir=root)
        run = store.load_run(swarm_id)
        if run is None or run.id != swarm_id:
            raise ValueError("research not found")
        return run, store, path.resolve()
    except (OSError, ValueError) as exc:
        raise HTTPException(status_code=404, detail="Native research not found") from exc


def native_catalog(limit: int = 20, offset: int = 0, source: str | None = None) -> dict[str, Any]:
    import yaml
    from src.strategy_discovery import StrategyDiscoveryFacade
    from src.swarm.presets import PRESETS_DIR

    teams = []
    for name in NATIVE_TEAM_NAMES:
        path = PRESETS_DIR / (name + ".yaml")
        raw = path.read_bytes()
        data = yaml.safe_load(raw)
        teams.append({"name": data["name"], "title": data["title"],
            "description": data["description"], "source": "bundled",
            "source_sha256": hashlib.sha256(raw).hexdigest(),
            "variables": data.get("variables", []),
            "tasks": [{key: task.get(key, []) if key == "depends_on" else task[key]
                for key in ("id", "agent_id", "depends_on")} for task in data["tasks"]],
            "agents": [{key: agent.get(key, []) if key in {"tools", "skills"} else agent[key]
                for key in ("id", "role", "tools", "skills")} for agent in data["agents"]]})
    return {"teams": teams, "strategies": StrategyDiscoveryFacade().list_strategies(
        limit=limit, offset=offset, source=source)}


def native_strategy(strategy_id: str) -> dict[str, Any]:
    from src.strategy_discovery import StrategyDiscoveryFacade
    from src.api.mona_operations import _resolve_run, _run_code_sha256

    if not isinstance(strategy_id, str) or not _STRATEGY.fullmatch(strategy_id) or ".." in strategy_id:
        raise HTTPException(status_code=404, detail="Native strategy not found")
    facade = StrategyDiscoveryFacade()
    # The facade returns a well-formed 'no evidence' envelope for unknown ids;
    # identity must therefore be checked against the actual native catalogue.
    summaries = facade._sdm_summaries() if strategy_id.startswith("sdm:") else facade._alpha_summaries()
    summary = next((item for item in summaries if item.strategy_id == strategy_id), None)
    if summary is None:
        raise HTTPException(status_code=404, detail="Native strategy not found")
    result = facade.get_strategy_evidence(strategy_id)
    result["linked_run"] = None
    description = result.get("description")
    if isinstance(description, dict):
        source_run = description.get("run_dir")
        if not source_run and isinstance(description.get("signal_engine_path"), str):
            engine_path = Path(description["signal_engine_path"])
            if engine_path.name == "signal_engine.py" and engine_path.parent.name == "code":
                source_run = str(engine_path.parent.parent)
        if isinstance(source_run, str) and source_run:
            try:
                source_path = Path(source_run).resolve(strict=True)
                if source_path.parent == get_runs_dir().resolve():
                    resolved = _resolve_run(source_path.name)
                    result["linked_run"] = {"run_id": source_path.name,
                        "config_sha256": hashlib.sha256((resolved / "config.json").read_bytes()).hexdigest(),
                        "code_sha256": _run_code_sha256(resolved)}
                elif source_path.is_relative_to(get_swarm_runs_dir().resolve()):
                    source_relative = source_path.relative_to(get_runtime_root().resolve()).as_posix()
                    config_sha = hashlib.sha256((source_path / "config.json").read_bytes()).hexdigest()
                    code_sha = _run_code_sha256(source_path)
                    for entry in list(get_runs_dir().iterdir())[:1000]:
                        manifest_path = entry / "mona_swarm_source.json"
                        if not manifest_path.is_file():
                            continue
                        try:
                            manifest = _json_file(manifest_path, get_runtime_root().resolve())
                        except (ValueError, OSError):
                            continue
                        if (manifest.get("source_relative_run_dir") == source_relative
                                and manifest.get("config_sha256") == config_sha and manifest.get("code_sha256") == code_sha
                                and manifest.get("run_id") == entry.name):
                            result["linked_run"] = {key: manifest[key] for key in ("run_id", "config_sha256", "code_sha256")}
                            break
            except (HTTPException, OSError, ValueError):
                pass
        # Opaque report identity is enough for the product; never project raw
        # local paths as navigation targets.
        result["description"] = {key: value for key, value in description.items()
            if key not in {"run_dir", "signal_engine_path"}}
    return redact_payload(result)


def _receipt_root(swarm_id: str) -> Path:
    if not _ID.fullmatch(swarm_id):
        raise ValueError("invalid research identity")
    return get_runtime_root() / "native-research" / swarm_id / "receipts"


def _workspace_run(run_dir: Path):
    try:
        root = get_swarm_runs_dir().resolve()
        resolved = run_dir.resolve(strict=True)
        if resolved.parent != root:
            return None
        run, _store, _path = _run(resolved.name)
        return run if run.preset_name in NATIVE_TEAM_NAMES else None
    except (HTTPException, OSError, ValueError):
        return None


def worker_runtime_context(run_dir: Path, task: SwarmTask) -> str:
    """Artifact contract and upstream read locations go in the user message."""
    if os.environ.get("VIBE_TRADING_HOSTED") != "1" or _workspace_run(run_dir) is None:
        return ""
    from src.swarm.task_store import TaskStore

    upstream = []
    store = TaskStore(run_dir)
    for identity in task.depends_on:
        try:
            saved = store.load_task(identity)
        except FileNotFoundError:
            continue
        upstream.append({"task_id": saved.id, "status": saved.status.value,
            "artifacts": [str((run_dir / value).resolve()) for value in saved.artifacts
                if isinstance(value, str) and (run_dir / value).resolve().is_relative_to((run_dir / "artifacts").resolve())]})
    return "\n\n## Product artifact delivery (runtime context)\n" + (
        "Keep the bundled team's financial method and task unchanged. Do not invent scores, data or candidates. "
        "If your actual task selects research candidates, also save candidates.json with write_file in your workspace: "
        '{"candidates":[{"symbol":"six digits plus verified exchange suffix","name":"observed company name or empty",'
        '"as_of":"YYYY-MM-DD from the actual observations","support":["your evidence-based selection reason"],'
        '"risks":["your evidence-based risk"],"evidence_refs":["actual successful data tool call id"]}]}. '
        "Only include candidates actually produced by your assigned method. Each evidence_refs entry must refer to "
        "a successful tool call in this run that actually returned the same symbol and observation date. "
        "If the provider does not expose call ids, omit evidence_refs: the host binds only recorded exact symbol/date observations. "
        "Call get_market_data if a symbol/date needs confirmation. Never use report prose as a data source. "
        "Numerical research roles may use the bundled get_market_data tool through the hosted adapter. "
        "Its _mona_data_snapshot or data_snapshot field identifies the complete original JSON data saved in your workspace. "
        "Read that snapshot with Python/read_file rather than reconstructing prices from memory or a truncated preview. "
        "If the task did not select candidates or evidence is missing, do not fabricate a list. "
        "Historical backtest positions are labelled separately as historical positions, never today's picks. "
        "The host makes same-run upstream artifacts read-only to read_file; write_file/edit_file/backtest stay in your own workspace.\n"
        + json.dumps({"upstream_artifacts": upstream}, ensure_ascii=False))


def worker_tool_names(run_dir: Path, agent_spec) -> list[str]:
    tools = list(agent_spec.tools)
    if os.environ.get("VIBE_TRADING_HOSTED") != "1" or _workspace_run(run_dir) is None:
        return tools
    numerical = bool(set(tools) & {"factor_analysis", "backtest"} or set(agent_spec.skills or []) & {
        "ml-strategy", "multi-factor", "factor-research", "strategy-generate", "quant-statistics", "volatility"})
    if numerical and "get_market_data" not in tools:
        tools.append("get_market_data")
    return tools


def shared_read_arguments(tool_name: str, arguments: dict[str, Any], run_dir: Path) -> dict[str, Any]:
    if tool_name != "read_file" or _workspace_run(run_dir) is None:
        return arguments
    root = (run_dir / "artifacts").resolve(strict=True)
    value = arguments.get("path")
    if not isinstance(value, str):
        return arguments
    path = Path(value)
    resolved = path.resolve() if path.is_absolute() else (Path(arguments["run_dir"]) / path).resolve()
    if resolved.is_relative_to(root):
        return {**arguments, "run_dir": str(root), "path": str(resolved)}
    return arguments


def _observations(value: Any) -> tuple[set[str], set[str], dict[str, list[str]]]:
    symbols, dates, paired = set(), set(), {}
    def visit(item, current_symbol=None):
        if isinstance(item, dict):
            own_symbol = next((item[key] for key in ("symbol", "code", "ts_code")
                if isinstance(item.get(key), str) and _SYMBOL.fullmatch(item[key])), current_symbol)
            if own_symbol:
                symbols.add(own_symbol)
            for key, child in item.items():
                if str(key).startswith("_"):
                    continue
                if _SYMBOL.fullmatch(str(key)) and child:
                    symbols.add(str(key))
                    visit(child, str(key))
                    continue
                if key in {"date", "trade_date", "timestamp", "ann_date", "as_of", "index"} and isinstance(child, str):
                    try:
                        day = date.fromisoformat(child[:10]).isoformat()
                        dates.add(day)
                        if own_symbol:
                            paired.setdefault(own_symbol, set()).add(day)
                    except ValueError:
                        pass
                visit(child, own_symbol)
        elif isinstance(item, list):
            for child in item:
                visit(child, current_symbol)
    visit(value)
    return symbols, dates, {key: sorted(values) for key, values in paired.items()}


def _publish_backtest(run, task_id: str, call_id: str, source: Path, workspace: Path) -> dict[str, Any]:
    """Publish an exact original-engine snapshot for existing report routes."""
    from src.api.mona_operations import _is_link, _run_code_sha256
    from src.tools.path_utils import safe_path

    source = safe_path(str(source), workspace)
    if _is_link(source) or not source.is_dir():
        raise ValueError("backtest input is outside the task workspace")
    config = _json_file(source / "config.json", get_runtime_root().resolve(), 1024 * 1024)
    state = _json_file(source / "state.json", get_runtime_root().resolve(), 1024 * 1024)
    if not isinstance(config, dict) or not isinstance(state, dict) or state.get("status") != "success":
        raise ValueError("backtest is not a successful original run")
    code_sha = _run_code_sha256(source)
    identity = "swarm-" + hashlib.sha256((run.id + "\0" + task_id + "\0" + call_id).encode()).hexdigest()[:32]
    root = get_runs_dir()
    if _is_link(root):
        raise ValueError("native report root is linked")
    root.mkdir(parents=True, exist_ok=True)
    root = root.resolve(strict=True)
    if root != get_runtime_root().resolve() / "runs":
        raise ValueError("native report root escapes runtime")
    target = root / identity
    link = {"run_id": identity, "swarm_id": run.id, "task_id": task_id, "call_id": call_id,
        "status": "success", "source_kind": "native_swarm_backtest",
        "source_relative_run_dir": source.relative_to(get_runtime_root().resolve()).as_posix(),
        "config_sha256": hashlib.sha256((source / "config.json").read_bytes()).hexdigest(),
        "code_sha256": code_sha}
    if target.exists():
        persisted = _json_file(target / "mona_swarm_source.json", root)
        if persisted != link:
            raise ValueError("published native run identity has conflicting contents")
        return link
    staging = root / (".publish-" + uuid.uuid4().hex)
    staging.mkdir()
    try:
        total = 0
        for path in sorted(source.rglob("*")):
            relative = path.relative_to(source)
            if relative.parts[0] not in {"config.json", "code", "artifacts", "logs", "state.json"}:
                continue
            if any(part in {"__pycache__", ".cache"} for part in relative.parts):
                continue
            if _is_link(path) or not path.resolve().is_relative_to(source):
                raise ValueError("backtest artifact escapes its task workspace")
            if path.is_dir():
                continue
            size = path.stat().st_size
            total += size
            if size > 128 * 1024 * 1024 or total > 256 * 1024 * 1024:
                raise ValueError("backtest report snapshot exceeds the artifact limit")
            destination = staging / relative
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(path, destination)
        if (hashlib.sha256((staging / "config.json").read_bytes()).hexdigest() != link["config_sha256"]
                or _run_code_sha256(staging) != code_sha):
            raise ValueError("backtest inputs changed during report publication")
        (staging / "mona_swarm_source.json").write_text(json.dumps(link, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        staging.rename(target)
        return link
    except Exception:
        if staging.resolve().parent == root:
            shutil.rmtree(staging)
        raise


def record_tool_receipt(run_dir: Path, artifact_dir: Path, task: SwarmTask,
        tool_name: str, call_id: str, arguments: dict[str, Any], result: str, is_error: bool) -> str | None:
    if os.environ.get("VIBE_TRADING_HOSTED") != "1":
        return None
    run = _workspace_run(run_dir)
    if run is None:
        return None
    parsed = None
    safe_result = redact_tool_result(result)
    if len(safe_result.encode("utf-8")) <= _MAX_JSON:
        try:
            parsed = json.loads(safe_result)
        except (ValueError, TypeError):
            pass
    receipt_id = hashlib.sha256((task.id + "\0" + call_id).encode()).hexdigest()
    observed, dates, paired_dates = _observations(parsed)
    receipt = {"receipt_id": receipt_id, "swarm_id": run.id, "task_id": task.id,
        "agent_id": task.agent_id, "call_id": call_id, "tool": tool_name,
        "status": "error" if is_error else "ok", "result_sha256": hashlib.sha256(result.encode("utf-8")).hexdigest(),
        "arguments": redact_payload({key: value for key, value in arguments.items() if key != "run_dir"}),
        "result": parsed, "observed_symbols": sorted(observed), "observation_dates": sorted(dates),
        "observation_dates_by_symbol": paired_dates,
        "linked_run": None, "strategy_ids": []}
    if tool_name == "get_market_data" and not is_error and isinstance(parsed, dict):
        from src.tools.path_utils import safe_path

        snapshot_root = safe_path("data", artifact_dir)
        snapshot_root.mkdir(parents=True, exist_ok=True)
        snapshot = safe_path("market_" + receipt_id[:24] + ".json", snapshot_root)
        content = (json.dumps(parsed, ensure_ascii=False, indent=2, allow_nan=False) + "\n").encode("utf-8")
        snapshot.write_bytes(content)
        receipt["data_snapshot"] = {"path": str(snapshot), "sha256": hashlib.sha256(content).hexdigest(),
            "bytes": len(content), "source_result_sha256": receipt["result_sha256"]}
    if tool_name in {"sdm_register", "adapt_strategy", "refresh_strategy_evidence"} and not is_error and isinstance(parsed, dict):
        identities = [parsed.get(key) for key in ("strategy_id", "artifact_id")]
        if isinstance(parsed.get("artifact"), dict):
            identities.append(parsed["artifact"].get("id"))
        for value in identities:
            if isinstance(value, str):
                identity = value if ":" in value else "sdm:" + value
                if _STRATEGY.fullmatch(identity):
                    try:
                        native_strategy(identity)
                        receipt["strategy_ids"].append(identity)
                    except HTTPException:
                        continue
    if tool_name == "backtest" and not is_error and isinstance(parsed, dict) and parsed.get("status") == "ok":
        try:
            receipt["linked_run"] = _publish_backtest(run, task.id, call_id, Path(arguments["run_dir"]), artifact_dir)
        except (HTTPException, OSError, ValueError) as exc:
            logger.warning("Native research backtest publication failed: %s", type(exc).__name__)
            receipt["publication_error"] = "native_backtest_report_publication_failed"
    root = _receipt_root(run.id)
    from src.api.mona_operations import _is_link
    from src.api.mona_reads import _safe_private_directory

    private_root = get_runtime_root().resolve()
    for path in (root.parent.parent, root.parent, root):
        if _is_link(path):
            raise ValueError("receipt directory may not be linked")
    root.mkdir(parents=True, exist_ok=True)
    safe_root = _safe_private_directory(root, private_root)
    if safe_root is None:
        raise ValueError("receipt directory escapes private state")
    root = safe_root
    path = root / (receipt_id + ".json")
    temporary = root / (".receipt-" + uuid.uuid4().hex)
    temporary.write_text(json.dumps(receipt, ensure_ascii=False, indent=2, allow_nan=False) + "\n", encoding="utf-8")
    temporary.replace(path)
    return receipt_id


def tool_result_delivery(swarm_id: str, receipt_id: str | None, original: str) -> str:
    """Hand the model a complete JSON result or an explicit full-data file ref."""
    if receipt_id is None:
        return original
    from src.config.limits import TOOL_RESULT_LIMIT

    receipt = _json_file(_receipt_root(swarm_id) / (receipt_id + ".json"), get_runtime_root().resolve())
    snapshot = receipt.get("data_snapshot")
    if not isinstance(snapshot, dict) or not isinstance(receipt.get("result"), dict):
        return original
    complete = {**receipt["result"], "_mona_data_snapshot": snapshot}
    delivery = json.dumps(complete, ensure_ascii=False)
    if len(delivery) <= TOOL_RESULT_LIMIT:
        return delivery
    return json.dumps({"status": "ok", "data_snapshot": snapshot,
        "requested_codes": receipt["arguments"].get("codes"),
        "requested_source": receipt["arguments"].get("source", "auto"),
        "requested_window": {key: receipt["arguments"].get(key) for key in ("start_date", "end_date", "interval")},
        "observed_symbols": receipt["observed_symbols"],
        "observation_ranges": {symbol: {"start": values[0], "end": values[-1]} for symbol, values in
            receipt["observation_dates_by_symbol"].items() if values},
        "message": "The complete original native data exceeds the model message budget and is saved at data_snapshot.path. Read that JSON file with Python/read_file. This is a file reference, not the full data."}, ensure_ascii=False)


def _receipts(swarm_id: str) -> list[dict[str, Any]]:
    root = _receipt_root(swarm_id)
    if not root.is_dir():
        return []
    receipts = []
    for path in sorted(root.glob("*.json"))[:5000]:
        if not re.fullmatch(r"[a-f0-9]{64}\.json", path.name):
            continue
        try:
            value = _json_file(path, get_runtime_root().resolve())
            if value.get("swarm_id") == swarm_id and value.get("receipt_id") == path.stem:
                snapshot = value.get("data_snapshot")
                if isinstance(snapshot, dict):
                    from src.api.mona_reads import _safe_private_regular_file

                    actual = _safe_private_regular_file(Path(snapshot.get("path", "")), get_runtime_root().resolve())
                    value["data_snapshot_matches"] = bool(actual and actual.stat().st_size <= _MAX_JSON
                        and hashlib.sha256(actual.read_bytes()).hexdigest() == snapshot.get("sha256"))
                receipts.append(value)
        except (OSError, ValueError, TypeError):
            logger.warning("Native research receipt unavailable: %s", path.name)
    return receipts


def _candidate_rows(run, paths: list[tuple[str, str, Path]], receipts: list[dict[str, Any]]) -> tuple[list, list]:
    by_call = {receipt["call_id"]: receipt for receipt in receipts
        if receipt.get("status") == "ok" and receipt.get("data_snapshot_matches", True) and receipt.get("tool") not in {
            "bash", "write_file", "read_file", "edit_file", "backtest", "load_skill"}}
    rows, sources = [], []
    for artifact_id, task_id, path in paths:
        if path.name != "candidates.json":
            continue
        try:
            payload = _json_file(path, get_runtime_root().resolve(), 1024 * 1024)
        except (OSError, ValueError):
            continue
        items = payload.get("candidates", []) if isinstance(payload, dict) else []
        if not isinstance(items, list):
            continue
        for item in items[:500]:
            if not isinstance(item, dict) or not _SYMBOL.fullmatch(str(item.get("symbol", ""))):
                continue
            symbol = item["symbol"]
            try:
                as_of = date.fromisoformat(item.get("as_of", "")).isoformat()
            except (TypeError, ValueError):
                continue
            refs = item.get("evidence_refs", [])
            if not isinstance(refs, list) or any(not isinstance(value, str) for value in refs):
                continue
            selected_refs = refs if refs else list(by_call)
            matches = [by_call[value] for value in selected_refs if value in by_call
                and symbol in by_call[value].get("observed_symbols", [])
                and as_of in by_call[value].get("observation_dates_by_symbol", {}).get(symbol, [])]
            if not matches or as_of > date.today().isoformat():
                continue
            support, risks = item.get("support", []), item.get("risks", [])
            if not isinstance(support, list) or not support or not isinstance(risks, list):
                continue
            if any(not isinstance(value, str) or len(value) > 1000 for value in support + risks):
                continue
            if any(row["symbol"] == symbol and row["as_of"] == as_of and row["task_id"] == task_id for row in rows):
                continue
            evidence = [{key: receipt[key] for key in ("receipt_id", "task_id", "call_id", "tool", "result_sha256")}
                for receipt in matches]
            name = item.get("name", "")
            rows.append({"symbol": symbol, "name": name[:128] if isinstance(name, str) else "",
                "as_of": as_of, "support": support, "risks": risks, "task_id": task_id,
                "artifact_id": artifact_id, "evidence_refs": evidence, "kind": "research_candidate",
                "evidence_verification": "tool_result_symbol_and_date"})
            sources.extend({**reference, "symbol": symbol, "as_of": as_of,
                "artifact_id": artifact_id} for reference in evidence)
    return rows, sources


def _historical_signals(linked_runs: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Project actual native target weights, never interpret them as new picks."""
    from src.api.mona_reads import _safe_private_regular_file

    rows = []
    for linked in linked_runs:
        root = get_runs_dir() / linked["run_id"]
        path = _safe_private_regular_file(root / "artifacts/target_positions.csv", get_runtime_root().resolve())
        if path is None or path.stat().st_size > 128 * 1024 * 1024:
            continue
        with path.open(encoding="utf-8-sig", newline="") as handle:
            final = None
            for row in csv.DictReader(handle):
                final = row
        if not final:
            continue
        time = final.get("timestamp") or next(iter(final.values()), "")
        try:
            as_of = date.fromisoformat(time[:10]).isoformat()
        except (TypeError, ValueError):
            continue
        for symbol, raw in final.items():
            if not _SYMBOL.fullmatch(str(symbol)):
                continue
            try:
                weight = float(raw)
            except (TypeError, ValueError):
                continue
            if not math.isfinite(weight) or weight <= 0:
                continue
            rows.append({"symbol": symbol, "name": "", "as_of": as_of,
                "task_id": linked["task_id"], "kind": "backtest_target", "weight": weight,
                "support": [f"原生策略在回测截至{as_of}的目标仓位为{weight:.2%}。"],
                "risks": ["这是该次历史回测的策略信号，不是今天重新选出的股票。"],
                "evidence_refs": [{"run_id": linked["run_id"], "artifact": "target_positions.csv",
                    "config_sha256": linked["config_sha256"], "code_sha256": linked["code_sha256"]}]})
    return rows


def native_research(swarm_id: str) -> dict[str, Any]:
    from src.api.mona_swarm_artifacts import _artifacts
    from src.swarm.task_store import TaskStore

    run, store, root = _run(swarm_id)
    task_store = TaskStore(root)
    tasks = []
    for task in run.tasks:
        try:
            saved = task_store.load_task(task.id)
        except FileNotFoundError:
            saved = task
        tasks.append({**serialize_task(saved), "artifacts": list(saved.artifacts)})
    paths = _artifacts(swarm_id)
    artifacts = [{"artifact_id": identity, "task_id": task, "filename": path.name,
        "bytes": path.stat().st_size,
        "sha256": hashlib.sha256(path.read_bytes()).hexdigest() if path.stat().st_size <= _MAX_JSON else None}
        for identity, task, path in paths]
    receipts = _receipts(swarm_id)
    linked = []
    warnings = []
    for receipt in receipts:
        if receipt.get("data_snapshot_matches") is False:
            warnings.append("部分行情资料快照已被修改或无法读取；原始调用回执仍保留，该快照不作为入选依据。")
        result = receipt.get("linked_run")
        if isinstance(result, dict) and _ID.fullmatch(result.get("run_id", "")):
            try:
                saved = _json_file(get_runs_dir() / result["run_id"] / "mona_swarm_source.json", get_runtime_root().resolve())
                if saved == result:
                    linked.append(result)
            except (ValueError, OSError):
                warnings.append("部分历史回测产物暂不可读取，研究记录仍保留。")
        if receipt.get("publication_error"):
            warnings.append("一次原生回测已执行，但报告目录整理未完成；可查看该任务原始产物。")
    candidates, sources = _candidate_rows(run, paths, receipts)
    historical = _historical_signals(linked)
    if not candidates and not historical:
        warnings.append("本次研究尚无带可核对资料来源的结构化股票名单；请查看任务报告与资料。")
    return {"id": run.id, "preset_name": run.preset_name, "status": run.status.value,
        "is_stale": store.is_run_stale(run), "user_vars": run.user_vars,
        "tasks": tasks, "final_report": run.final_report,
        "grounding_metadata": run.grounding_metadata,
        "artifacts": artifacts, "linked_runs": linked,
        "strategy_ids": sorted({identity for receipt in receipts for identity in receipt.get("strategy_ids", [])}),
        "candidates": candidates, "historical_signals": historical, "candidate_sources": sources,
        "warnings": list(dict.fromkeys(warnings)), "created_at": run.created_at, "completed_at": run.completed_at}


def resolve_native_research_context(value: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) - {"swarm_id", "task_id", "strategy_id", "symbol"}:
        raise ValueError("invalid native research source")
    if ("swarm_id" in value) == ("strategy_id" in value):
        raise ValueError("select exactly one native research or strategy source")
    if "strategy_id" in value:
        if set(value) != {"strategy_id"}:
            raise ValueError("strategy sources cannot carry research task fields")
        evidence = native_strategy(value["strategy_id"])
        reads = [{"tool": "get_strategy_evidence", "arguments": {"strategy_id": value["strategy_id"]}}]
        linked = evidence.get("linked_run")
        if isinstance(linked, dict):
            reads.append({"tool": "read_run_artifact", "arguments": {
                "run_dir": str((get_runs_dir() / linked["run_id"]).resolve()), "artifact": "run_card"}})
        return {"source": "strategy", "strategy_id": value["strategy_id"], "evidence": evidence,
            "native_read_tools": reads}
    result = native_research(value["swarm_id"])
    tasks = result["tasks"]
    task_id = value.get("task_id")
    if task_id is not None:
        tasks = [item for item in tasks if item["id"] == task_id]
        if not tasks:
            raise ValueError("task is not part of this native research")
    symbol = value.get("symbol")
    candidate = None
    if symbol is not None:
        from src.api.mona_backtest_settings import _symbol

        if not isinstance(symbol, str):
            raise ValueError("invalid native candidate symbol")
        symbol = _symbol(symbol)
        candidate = next((item for item in result["candidates"] + result["historical_signals"]
            if item["symbol"] == symbol and (task_id is None or item["task_id"] == task_id)), None)
        if candidate is None:
            raise ValueError("stock is not a recorded native candidate or historical signal")
    from src.api.mona_swarm_artifacts import _artifacts

    reads = [{"tool": "read_file", "task_id": identity, "artifact_id": artifact,
        "arguments": {"path": str(path)}} for artifact, identity, path in _artifacts(result["id"])
        if task_id is None or identity == task_id]
    return {"source": "swarm", "swarm_id": result["id"], "preset_name": result["preset_name"],
        "status": result["status"], "task_id": task_id, "symbol": symbol, "candidate": candidate,
        "tasks": tasks, "grounding_metadata": result["grounding_metadata"], "linked_runs": result["linked_runs"],
        "native_read_tools": reads}


def format_native_research_context(context: dict[str, Any]) -> str:
    return ("## Native research source (read-only runtime context)\n"
        "This is the persisted source for the user's current question, not a new execution request. "
        "Cite the saved task, tool receipt and original report; do not fabricate a candidate or inherit past performance. "
        "Use the exact native_read_tools read_file/read_run_artifact arguments to inspect saved artifacts; do not guess paths. "
        "For registered strategy reuse, read get_strategy_evidence, load strategy-generate and use adapt_strategy "
        "only under its native evidence and modification rules. Generate and backtest the child's own inputs; "
        "do not copy the parent's metrics.\n" + json.dumps(context, ensure_ascii=False))


def register_native_research(app: FastAPI) -> None:
    if os.environ.get("VIBE_TRADING_HOSTED") != "1":
        return

    @app.get("/mona/native-research/catalog", dependencies=[Depends(require_auth)])
    def catalog(limit: int = Query(20, ge=1, le=100), offset: int = Query(0, ge=0), source: str | None = None):
        if source not in (None, "alpha_zoo", "sdm"):
            raise HTTPException(status_code=422, detail="invalid native strategy source")
        return native_catalog(limit, offset, source)

    @app.get("/mona/native-research/strategies/{strategy_id}", dependencies=[Depends(require_auth)])
    def strategy(strategy_id: str):
        return native_strategy(strategy_id)

    @app.get("/mona/native-research/{swarm_id}/evidence/{receipt_id}", dependencies=[Depends(require_auth)])
    def evidence(swarm_id: str, receipt_id: str):
        _run(swarm_id)
        if not re.fullmatch(r"[a-f0-9]{64}", receipt_id):
            raise HTTPException(status_code=404, detail="Native research evidence not found")
        try:
            value = _json_file(_receipt_root(swarm_id) / (receipt_id + ".json"), get_runtime_root().resolve())
            if value.get("swarm_id") != swarm_id or value.get("receipt_id") != receipt_id:
                raise ValueError("mismatched evidence identity")
            return value
        except (OSError, ValueError) as exc:
            raise HTTPException(status_code=404, detail="Native research evidence not found") from exc

    @app.get("/mona/native-research/{swarm_id}", dependencies=[Depends(require_auth)])
    def detail(swarm_id: str):
        return native_research(swarm_id)
